fun nextStep(granted: Boolean, shouldShowRationale: Boolean): String = when {
    granted -> "использовать"
    shouldShowRationale -> "объяснить"
    else -> "спросить"
}

fun main() {
    println(nextStep(true, false))
    println(nextStep(false, true))
    println(nextStep(false, false))
}

fun canNotify(sdk: Int, granted: Boolean): Boolean = sdk < 33 || granted

fun main() {
    println(canNotify(30, false))
    println(canNotify(33, false))
    println(canNotify(34, true))
}

fun tasksText(n: Int): String {
    val word = when {
        n % 100 in 11..14 -> "задач"
        n % 10 == 1 -> "задача"
        n % 10 in 2..4 -> "задачи"
        else -> "задач"
    }
    return "У вас $n $word"
}

fun main() {
    println(tasksText(1))
    println(tasksText(3))
    println(tasksText(5))
    println(tasksText(11))
    println(tasksText(21))
}
